window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3badaa1e7ed83a48"]={"versions": [{"id": "FIG-3badaa1e7ed83a48", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Metamodell-Klassendiagramm (UML Class Diagram), AUTOSAR Adaptive Platform (TPS Manifest Specification, R23-11, Kapitel 15 <em>Package Management</em>).\n</li><li><strong>Technischer Zweck:</strong> Definition der Vererbungshierarchie für <code>UploadableDesignElement</code>. Es spezifiziert sämtliche modellbasierten Konfigurations- und Design-Artefakte (ARXML), die über das AUTOSAR Adaptive <em>Update and Configuration Management</em> (UCM) als eigenständige Software Packages bzw. Deployable Content auf eine Zielmaschine übertragen, aktualisiert oder gepatcht werden können, ohne die gesamte Systemkonfiguration neu flashen zu müssen.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Basis-Klassenhierarchie</h5>\n<ul class=\"fig-list\"><li><strong><code>UploadablePackageElement</code></strong> (<code>ARElement</code>, abstrakt): Wurzelklasse für alle paketierbaren Manifest- und Design-Entitäten innerhalb eines Software Packages.\n</li><li><strong><code>UploadableDesignElement</code></strong> (abstrakt): Direkte Spezialisierung (<code>Generalization</code>) von <code>UploadablePackageElement</code>. Dient als polymorpher Ankerpunkt für alle Entwurfselemente der System-, Netzwerk-, Sicherheits- und Servicearchitektur.\n</li></ul>\n<h5 class=\"fig-section-h5\">Abgeleitete Spezialisierungen (Subklassen von <code>UploadableDesignElement</code>)</h5>\n<ol class=\"fig-list\"><li><strong>Service-Oriented Communication &amp; Deployment (ara::com / Middleware):</strong>\n<ul class=\"fig-list\"><li><code>ServiceInterfaceDeployment</code>: Protokollspezifische Bindung von Schnittstellen (SOME/IP, DDS, IPC).\n</li><li><code>ServiceInstanceToPortPrototypeMapping</code>: Zuordnung von Service-Instanzen zu Port-Prototypen einer Softwarekomponente.\n</li><li><code>ServiceInstanceToMachineMapping</code>: Bindung einer Service-Instanz an eine konkrete Maschine (Netzwerk-Endpunkt).\n</li><li><code>ServiceInstanceToSignalMapping</code> &amp; <code>SignalServiceTranslationPropsSet</code> (<code>ARElement</code>): Gateway-Mapping zwischen klassischer signalbasierter Kommunikation (CAN/LIN/FlexRay) und serviceorientierten Events/Methoden.\n</li><li><strong>SOME/IP-Spezifika:</strong>\n<ul class=\"fig-list\"><li><code>SomeipRemoteUnicastConfig</code>, <code>SomeipRemoteMulticastConfig</code> (<code>ARElement</code>).\n</li><li><code>SomeipSdClientServiceInstanceConfig</code>, <code>SomeipSdServerServiceInstanceConfig</code> (<code>ARElement</code>): SD-Timing und Instanzkonfiguration.\n</li><li><code>SomeipSdClientEventGroupTimingConfig</code>, <code>SomeipSdServerEventGroupTimingConfig</code> (<code>ARElement</code>).\n</li><li><code>SomeipDataPrototypeTransformationProps</code>, <code>TransformationPropsSet</code>, <code>TransformationPropsToServiceInterfaceElementMapping</code>, <code>TlvDataIdDefinitionSet</code> (<code>ARElement</code>): Serialisierungs- und TLV-Encoding-Regeln.\n</li></ul>\n</li><li><strong>DDS-Spezifika:</strong> <code>DdsSecureGovernance</code>, <code>DdsTopicAccessRule</code> (Zugriffs- und Sicherheitsrichtlinien für DDS-Topics).\n</li></ul>\n</li><li><strong>Netzwerk-, Bus- &amp; Protokoll-Stack (FIBEX / Classic &amp; Adaptive Interop):</strong>\n<ul class=\"fig-list\"><li><code>CommunicationCluster</code> (<code>FibexElement</code>, Stereotyp <code>«atpVariation»</code>): Repräsentation von Bus-Clustern (Ethernet, CAN, CAN XL) mit Unterstützung für Variantenbildung.\n</li><li><code>CanXlProps</code> (<code>ARElement</code>): Spezifische Frame- und Bitraten-Parameter für CAN XL.\n</li><li><code>Pdu</code>, <code>ISignal</code>, <code>ISignalGroup</code> (<code>FibexElement</code>): Signal- und PDU-Definitionen für deterministische Buskommunikation.\n</li><li><code>SocketConnectionIpduIdentifierSet</code> (<code>FibexElement</code>): PDU-zu-Socket-Multiplexing über TCP/UDP.\n</li><li><code>EthIpProps</code>, <code>EthTcpIpProps</code>, <code>EthTcpIpIcmpProps</code> (<code>ARElement</code>): Parameter für IP/TCP/UDP/ICMP-Stacks (Subnetzmasken, MTU, Window Sizes).\n</li><li><code>NmConfig</code> (<code>FibexElement</code>): Network Management-Konfiguration (AUTOSAR NM / UDP NM).\n</li><li><code>GlobalTimeDomain</code> (<code>FibexElement</code>): Synchronisationsdomäne für gPTP / IEEE 802.1AS (ara::tsync).\n</li></ul>\n</li><li><strong>Security, Krypto &amp; Intrusion Detection (ara::crypto, IDS, Firewall):</strong>\n<ul class=\"fig-list\"><li><code>CryptoServicePrimitive</code>, <code>CryptoServiceKey</code>, <code>CryptoServiceCertificate</code> (<code>ARElement</code>): Konfiguration kryptografischer Algorithmen, Schlüsselzertifikate und Key-Slots.\n</li><li><code>SecureComProps</code>, <code>IPSecConfigProps</code> (<code>ARElement</code>): Konfiguration gesicherter IP-Verbindungen.\n</li><li><code>MacSecParticipantSet</code>, <code>MacSecGlobalKayProps</code> [sic: Modell-Typo für <em>Key</em>] (<code>ARElement</code>): Link-Layer-Verschlüsselung nach IEEE 802.1AE.\n</li><li><code>FirewallRule</code>, <code>StateDependentFirewall</code>: Paketfilter- und Routing-Regeln, abhängig vom Fahrzeug-/Systemzustand.\n</li><li><code>IdsCommonElement</code>, <code>IdsDesign</code> (<code>ARElement</code>), <code>SecurityEventReportToSecurityEventDefinitionMapping</code>: On-board Intrusion Detection System (IDS / IdsM) Architekturelemente und Security-Event-Filter.\n</li></ul>\n</li><li><strong>Safety, Logging, Tracing &amp; Diagnostik (ara::diag, ara::log):</strong>\n<ul class=\"fig-list\"><li><code>E2EProfileConfigurationSet</code>, <code>E2EProfileCompatibilityProps</code> (<code>ARElement</code>): End-to-End-Datenschutzprofile (Data ID, CRC-Offset, Window Size).\n</li><li><code>DltEcu</code>, <code>DltContext</code>, <code>LogAndTraceMessageCollectionSet</code> (<code>ARElement</code>): DLT-Logging-Kontexte und Filterkataloge.\n</li></ul>\n</li><li><strong>Topologie, Ausführungseinheiten &amp; Zustandsverwaltung (ara::exec):</strong>\n<ul class=\"fig-list\"><li><code>System</code> (<code>ARElement</code>, <code>AtpStructureElement</code>): Gesamtsystemdefinition.\n</li><li><code>MachineDesign</code> (<code>AtpStructureElement</code>, <code>FibexElement</code>): Hardware- und Netzwerktopologie einer Maschine vor der Software-Allokation.\n</li><li><code>Executable</code> (<code>AtpClassifier</code>): Definition des ausführbaren Binaries (ELF), das später zu einem <code>Process</code> instantiiert wird.\n</li><li><code>FunctionGroupSet</code> (<code>AtpClassifier</code>): Zusammenfassung logischer Funktionsgruppen für State Management.\n</li><li><code>ModeDeclarationGroup</code> (<code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>): Modus- und Zustandsraum-Definitionen.\n</li><li><code>Documentation</code> (<code>ARElement</code>): Modellierte Entwurfsspezifikation/Dokumentation.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches AUTOSAR-Metamodell existiert kein direkter Call-Stack oder sequenzielles Laufzeitverhalten. Die dynamische Relevanz greift im <strong>UCM-Lifecycle</strong>:</p>\n<ol class=\"fig-list\"><li><strong>Paket-Ingestion:</strong> UCM (<code>ara::ucm</code>) empfängt ein Software Package (<code>SwPackage</code>), dessen Manifest auf <code>UploadablePackageElement</code> verweist.\n</li><li><strong>Metamodell-Auflösung:</strong> Der Manifest-Parser validiert die Subklassen von <code>UploadableDesignElement</code> gegen die Schemata der Plattform.\n</li><li><strong>Inkrementelle Rekonfiguration:</strong>\n<ul class=\"fig-list\"><li>Werden z. B. <code>FirewallRule</code> oder <code>StateDependentFirewall</code> aktualisiert, triggert der UCM-Aktivierungsschritt eine Neugenerierung bzw. Neuladung der OS-/Kernel-Netfilter-Tabellen.\n</li><li>Wird ein <code>ServiceInstanceToMachineMapping</code> aktualisiert, rekonfiguriert der ara::com Service-Discovery-Daemon (SOME/IP SD / DDS Discovery) die lokalen Endpunkte zur Laufzeit.\n</li><li>Änderungen an <code>ModeDeclarationGroup</code> oder <code>FunctionGroupSet</code> synchronisieren die Zustandsübergänge im Execution Management (<code>ara::exec</code>).\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>UCM-Granularität &amp; Entkopplung:</strong> Entwickler von Adaptive-Anwendungen müssen Design-Artefakte strikt modular modellieren. Da alle dargestellten Klassen eigenständige <code>UploadableDesignElement</code>-Objekte sind, können Netzwerkmatrizen (FIBEX/Signals), Diagnosekonfigurationen (DLT) und Sicherheitsrichtlinien getrennt von den eigentlichen Executables aktualisiert werden.\n</li><li><strong>Manifest-Generierung:</strong> Toolchains (Generatoren) kompilieren diese M2-Elemente in spezifische Manifeste:\n<ul class=\"fig-list\"><li><code>Executable</code>, <code>FunctionGroupSet</code> → <em>Execution Manifest</em> (<code>.arxml</code> / JSON / BSON).\n</li><li><code>ServiceInterfaceDeployment</code>, <code>ServiceInstanceToPortPrototypeMapping</code> → <em>Service Instance Manifest</em>.\n</li><li><code>MachineDesign</code>, <code>EthTcpIpProps</code>, <code>CryptoService*</code> → <em>Machine Manifest</em>.\n</li></ul>\n</li><li><strong>Variantenmanagement:</strong> Da <code>CommunicationCluster</code> das Stereotyp <code>«atpVariation»</code> trägt, müssen Post-Build- bzw. Pre-Compile-Variationspunkte aufgelöst sein, bevor UCM ein deploybares Artefakt bindet.\n</li><li><strong>Sicherheitsimplikation:</strong> Durch das Uploaden von <code>CryptoServiceKey</code>, <code>IPSecConfigProps</code> oder <code>FirewallRule</code> müssen strikte Signaturprüfungen und Zugriffsrechte (UCM-Authentifizierung) greifen, um unautorisierte Rekonfigurationen von IDS/Firewall-Subsystemen auf Machine-Ebene zu verhindern.\n</li></ul>"}, {"id": "FIG-129ae5813a2d9c71", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Metamodell-Klassendiagramm (UML Class Diagram), AUTOSAR Adaptive Platform (TPS Manifest Specification, R23-11, Kapitel 15 <em>Package Management</em>).\n</li><li><strong>Technischer Zweck:</strong> Definition der Vererbungshierarchie für <code>UploadableDesignElement</code>. Es spezifiziert sämtliche modellbasierten Konfigurations- und Design-Artefakte (ARXML), die über das AUTOSAR Adaptive <em>Update and Configuration Management</em> (UCM) als eigenständige Software Packages bzw. Deployable Content auf eine Zielmaschine übertragen, aktualisiert oder gepatcht werden können, ohne die gesamte Systemkonfiguration neu flashen zu müssen.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Basis-Klassenhierarchie</h5>\n<ul class=\"fig-list\"><li><strong><code>UploadablePackageElement</code></strong> (<code>ARElement</code>, abstrakt): Wurzelklasse für alle paketierbaren Manifest- und Design-Entitäten innerhalb eines Software Packages.\n</li><li><strong><code>UploadableDesignElement</code></strong> (abstrakt): Direkte Spezialisierung (<code>Generalization</code>) von <code>UploadablePackageElement</code>. Dient als polymorpher Ankerpunkt für alle Entwurfselemente der System-, Netzwerk-, Sicherheits- und Servicearchitektur.\n</li></ul>\n<h5 class=\"fig-section-h5\">Abgeleitete Spezialisierungen (Subklassen von <code>UploadableDesignElement</code>)</h5>\n<ol class=\"fig-list\"><li><strong>Service-Oriented Communication &amp; Deployment (ara::com / Middleware):</strong>\n<ul class=\"fig-list\"><li><code>AdaptivePlatformServiceInstance</code>: Modellierung von serviceorientierten Plattform-Service-Instanzen auf der Adaptive Platform.\n</li><li><code>ServiceInterfaceDeployment</code>: Protokollspezifische Bindung von Schnittstellen (SOME/IP, DDS, IPC).\n</li><li><code>ServiceInstanceToPortPrototypeMapping</code>: Zuordnung von Service-Instanzen zu Port-Prototypen einer Softwarekomponente.\n</li><li><code>ServiceInstanceToMachineMapping</code>: Bindung einer Service-Instanz an eine konkrete Maschine (Netzwerk-Endpunkt).\n</li><li><code>ServiceInstanceToSignalMapping</code> &amp; <code>SignalServiceTranslationPropsSet</code> (<code>ARElement</code>): Gateway-Mapping zwischen klassischer signalbasierter Kommunikation (CAN/LIN/FlexRay) und serviceorientierten Events/Methoden.\n</li><li><strong>SOME/IP-Spezifika:</strong>\n<ul class=\"fig-list\"><li><code>SomeipRemoteUnicastConfig</code>, <code>SomeipRemoteMulticastConfig</code> (<code>ARElement</code>).\n</li><li><code>SomeipSdClientServiceInstanceConfig</code>, <code>SomeipSdServerServiceInstanceConfig</code> (<code>ARElement</code>): SD-Timing und Instanzkonfiguration.\n</li><li><code>SomeipSdClientEventGroupTimingConfig</code>, <code>SomeipSdServerEventGroupTimingConfig</code> (<code>ARElement</code>).\n</li><li><code>SomeipDataPrototypeTransformationProps</code>, <code>TransformationPropsSet</code>, <code>TransformationPropsToServiceInterfaceElementMapping</code>, <code>TlvDataIdDefinitionSet</code> (<code>ARElement</code>): Serialisierungs- und TLV-Encoding-Regeln.\n</li></ul>\n</li><li><strong>DDS-Spezifika:</strong> <code>DdsSecureGovernance</code>, <code>DdsTopicAccessRule</code> (Zugriffs- und Sicherheitsrichtlinien für DDS-Topics).\n</li></ul>\n</li><li><strong>Netzwerk-, Bus- &amp; Protokoll-Stack (FIBEX / Classic &amp; Adaptive Interop):</strong>\n<ul class=\"fig-list\"><li><code>CommunicationCluster</code> (<code>FibexElement</code>, Stereotyp <code>«atpVariation»</code>): Repräsentation von Bus-Clustern (Ethernet, CAN, CAN XL) mit Unterstützung für Variantenbildung.\n</li><li><code>CanXlProps</code> (<code>ARElement</code>): Spezifische Frame- und Bitraten-Parameter für CAN XL.\n</li><li><code>GenericTpConnection</code>: Generische Transportprotokoll-Verbindung für segmentierte Datenübertragung.\n</li><li><code>Pdu</code>, <code>ISignal</code>, <code>ISignalGroup</code> (<code>FibexElement</code>): Signal- und PDU-Definitionen für deterministische Buskommunikation.\n</li><li><code>SocketConnectionIpduIdentifierSet</code> (<code>FibexElement</code>): PDU-zu-Socket-Multiplexing über TCP/UDP.\n</li><li><code>EthIpProps</code>, <code>EthTcpIpProps</code>, <code>EthTcpIpIcmpProps</code> (<code>ARElement</code>): Parameter für IP/TCP/UDP/ICMP-Stacks (Subnetzmasken, MTU, Window Sizes).\n</li><li><code>NmConfig</code> (<code>FibexElement</code>): Network Management-Konfiguration (AUTOSAR NM / UDP NM).\n</li><li><code>GlobalTimeDomain</code> (<code>FibexElement</code>): Synchronisationsdomäne für gPTP / IEEE 802.1AS (ara::tsync).\n</li></ul>\n</li><li><strong>Security, Krypto &amp; Intrusion Detection (ara::crypto, IDS, Firewall):</strong>\n<ul class=\"fig-list\"><li><code>CryptoServicePrimitive</code>, <code>CryptoServiceKey</code>, <code>CryptoServiceCertificate</code> (<code>ARElement</code>): Spezifikation kryptografischer Primitive, Schlüssel und X.509-Zertifikate.\n</li><li><code>CryptoKeySlotUserDesign</code>, <code>CryptoKeySlotUserDesignMapping</code>, <code>CryptoKeySlotUsageDesignMapping</code>: Design-Elemente und Mappings zur Zuweisung und Nutzung von kryptografischen Key-Slots durch Applikationen und Plattformdienste.\n</li><li><code>SecureComProps</code>, <code>IPSecConfigProps</code> (<code>ARElement</code>): Parameter für gesicherte Kommunikationskanäle und IPsec.\n</li><li><code>MacSecParticipantSet</code>, <code>MacSecGlobalKeyProps</code> (<code>ARElement</code>): MACsec-Teilnehmer und globale Schlüssel auf Verbindungsschicht.\n</li><li><code>IdsDesign</code>, <code>IdsCommonElement</code> (<code>ARElement</code>), <code>SecurityEventReportToSecurityEventDefinitionMapping</code>: Intrusion Detection System (IDS) Architektur und Event-Mappings.\n</li><li><code>FirewallRule</code> (<code>ARElement</code>), <code>StateDependentFirewall</code>: Paketfilter und zustandsabhängige Firewall-Konfigurationen.\n</li></ul>\n</li><li><strong>Execution Management, State Management &amp; System-Topologie:</strong>\n<ul class=\"fig-list\"><li><code>Executable</code> (<code>AtpClassifier</code>): Definition ausführbarer Binärdateien im Software Package.\n</li><li><code>FunctionGroupSet</code> (<code>AtpClassifier</code>), <code>ModeDeclarationGroup</code> (<code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>): Funktionsgruppen und Modus-Deklarationen für State Management.\n</li><li><code>MachineDesign</code> (<code>AtpStructureElement</code>, <code>FibexElement</code>): Hardware- und Netzwerkarchitektur der Maschine.\n</li><li><code>System</code> (<code>ARElement</code>, <code>AtpStructureElement</code>): Systemweites Integrationsmodell.\n</li><li><code>Documentation</code> (<code>ARElement</code>): Dokumentations- und Spezifikationsmetadaten.\n</li></ul>\n</li><li><strong>Logging, Tracing &amp; End-to-End Protection:</strong>\n<ul class=\"fig-list\"><li><code>DltEcu</code>, <code>DltContext</code> (<code>ARElement</code>), <code>LogAndTraceMessageCollectionSet</code> (<code>ARElement</code>): Konfiguration für Diagnostic Log and Trace (ara::dlt).\n</li><li><code>E2EProfileConfigurationSet</code>, <code>E2EProfileCompatibilityProps</code> (<code>ARElement</code>): End-to-End-Absicherungsprofile und Kompatibilitätseigenschaften.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches AUTOSAR-Metamodell existiert kein direkter Call-Stack oder sequenzielles Laufzeitverhalten. Die dynamische Relevanz greift im <strong>UCM-Lifecycle</strong>:</p>\n<ol class=\"fig-list\"><li><strong>Paket-Ingestion:</strong> UCM (<code>ara::ucm</code>) empfängt ein Software Package (<code>SwPackage</code>), dessen Manifest auf <code>UploadablePackageElement</code> verweist.\n</li><li><strong>Metamodell-Auflösung:</strong> Der Manifest-Parser validiert die Subklassen von <code>UploadableDesignElement</code> gegen die Schemata der Plattform.\n</li><li><strong>Inkrementelle Rekonfiguration:</strong>\n<ul class=\"fig-list\"><li>Werden z. B. <code>FirewallRule</code> oder <code>StateDependentFirewall</code> aktualisiert, triggert der UCM-Aktivierungsschritt eine Neugenerierung bzw. Neuladung der OS-/Kernel-Netfilter-Tabellen.\n</li><li>Wird ein <code>ServiceInstanceToMachineMapping</code> aktualisiert, rekonfiguriert der ara::com Service-Discovery-Daemon (SOME/IP SD / DDS Discovery) die lokalen Endpunkte zur Laufzeit.\n</li><li>Änderungen an <code>ModeDeclarationGroup</code> oder <code>FunctionGroupSet</code> synchronisieren die Zustandsübergänge im Execution Management (<code>ara::exec</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>UCM-Granularität &amp; Entkopplung:</strong> Entwickler von Adaptive-Anwendungen müssen Design-Artefakte strikt modular modellieren. Da alle dargestellten Klassen eigenständige <code>UploadableDesignElement</code>-Objekte sind, können Netzwerkmatrizen (FIBEX/Signals), Diagnosekonfigurationen (DLT) und Sicherheitsrichtlinien getrennt von den eigentlichen Executables aktualisiert werden.\n</li><li><strong>Manifest-Generierung:</strong> Toolchains (Generatoren) kompilieren diese M2-Elemente in spezifische Manifeste:\n<ul class=\"fig-list\"><li><code>Executable</code>, <code>FunctionGroupSet</code> → <em>Execution Manifest</em> (<code>.arxml</code> / JSON / BSON).\n</li><li><code>ServiceInterfaceDeployment</code>, <code>ServiceInstanceToPortPrototypeMapping</code> → <em>Service Instance Manifest</em>.\n</li><li><code>MachineDesign</code>, <code>EthTcpIpProps</code>, <code>CryptoService*</code> → <em>Machine Manifest</em>.\n</li></ul>\n</li><li><strong>Variantenmanagement:</strong> Da <code>CommunicationCluster</code> das Stereotyp <code>«atpVariation»</code> trägt, müssen Post-Build- bzw. Pre-Compile-Variationspunkte aufgelöst sein, bevor UCM ein deploybares Artefakt bindet.\n</li><li><strong>Sicherheitsimplikation:</strong> Durch das Uploaden von <code>CryptoServiceKey</code>, <code>IPSecConfigProps</code> oder <code>FirewallRule</code> müssen strikte Signaturprüfungen und Zugriffsrechte (UCM-Authentifizierung) greifen, um unautorisierte Rekonfigurationen von IDS/Firewall-Subsystemen auf Machine-Ebene zu verhindern.\n</li></ul>"}, {"id": "FIG-b319b061c3e65dce", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Metamodell-Klassendiagramm (UML Class Diagram), AUTOSAR Adaptive Platform (TPS Manifest Specification, R23-11, Kapitel 15 <em>Package Management</em>).\n</li><li><strong>Technischer Zweck:</strong> Definition der Vererbungshierarchie für <code>UploadableDesignElement</code>. Es spezifiziert sämtliche modellbasierten Konfigurations- und Design-Artefakte (ARXML), die über das AUTOSAR Adaptive <em>Update and Configuration Management</em> (UCM) als eigenständige Software Packages bzw. Deployable Content auf eine Zielmaschine übertragen, aktualisiert oder gepatcht werden können, ohne die gesamte Systemkonfiguration neu flashen zu müssen.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Basis-Klassenhierarchie</h5>\n<ul class=\"fig-list\"><li><strong><code>UploadablePackageElement</code></strong> (<code>ARElement</code>, abstrakt): Wurzelklasse für alle paketierbaren Manifest- und Design-Entitäten innerhalb eines Software Packages.\n</li><li><strong><code>UploadableDesignElement</code></strong> (abstrakt): Direkte Spezialisierung (<code>Generalization</code>) von <code>UploadablePackageElement</code>. Dient als polymorpher Ankerpunkt für alle Entwurfselemente der System-, Netzwerk-, Sicherheits- und Servicearchitektur.\n</li></ul>\n<h5 class=\"fig-section-h5\">Abgeleitete Spezialisierungen (Subklassen von <code>UploadableDesignElement</code>)</h5>\n<ol class=\"fig-list\"><li><strong>Service-Oriented Communication &amp; Deployment (ara::com / Middleware):</strong>\n<ul class=\"fig-list\"><li><code>AdaptivePlatformServiceInstance</code>: Modellierung von serviceorientierten Plattform-Service-Instanzen auf der Adaptive Platform.\n</li><li><code>ServiceInterfaceDeployment</code>: Protokollspezifische Bindung von Schnittstellen (SOME/IP, DDS, IPC).\n</li><li><code>ServiceInstanceToPortPrototypeMapping</code>: Zuordnung von Service-Instanzen zu Port-Prototypen einer Softwarekomponente.\n</li><li><code>ServiceInstanceToMachineMapping</code>: Bindung einer Service-Instanz an eine konkrete Maschine (Netzwerk-Endpunkt).\n</li><li><code>ServiceInstanceToSignalMapping</code> &amp; <code>SignalServiceTranslationPropsSet</code> (<code>ARElement</code>): Gateway-Mapping zwischen klassischer signalbasierter Kommunikation (CAN/LIN/FlexRay) und serviceorientierten Events/Methoden.\n</li><li><strong>SOME/IP-Spezifika:</strong>\n<ul class=\"fig-list\"><li><code>SomeipRemoteUnicastConfig</code>, <code>SomeipRemoteMulticastConfig</code> (<code>ARElement</code>).\n</li><li><code>SomeipSdClientServiceInstanceConfig</code>, <code>SomeipSdServerServiceInstanceConfig</code> (<code>ARElement</code>): SD-Timing und Instanzkonfiguration.\n</li><li><code>SomeipSdClientEventGroupTimingConfig</code>, <code>SomeipSdServerEventGroupTimingConfig</code> (<code>ARElement</code>).\n</li><li><code>SomeipDataPrototypeTransformationProps</code>, <code>TransformationPropsSet</code>, <code>TransformationPropsToServiceInterfaceElementMapping</code>, <code>TlvDataIdDefinitionSet</code> (<code>ARElement</code>): Serialisierungs- und TLV-Encoding-Regeln.\n</li></ul>\n</li><li><strong>DDS-Spezifika:</strong> <code>DdsSecureGovernance</code>, <code>DdsTopicAccessRule</code> (Zugriffs- und Sicherheitsrichtlinien für DDS-Topics).\n</li></ul>\n</li><li><strong>Netzwerk-, Bus- &amp; Protokoll-Stack (FIBEX / Classic &amp; Adaptive Interop):</strong>\n<ul class=\"fig-list\"><li><code>CommunicationCluster</code> (<code>FibexElement</code>, Stereotyp <code>«atpVariation»</code>): Repräsentation von Bus-Clustern (Ethernet, CAN, CAN XL) mit Unterstützung für Variantenbildung.\n</li><li><code>CanXlProps</code> (<code>ARElement</code>): Spezifische Frame- und Bitraten-Parameter für CAN XL.\n</li><li><code>GenericTpConnection</code>: Generische Transportprotokoll-Verbindung für segmentierte Datenübertragung.\n</li><li><code>Pdu</code>, <code>ISignal</code>, <code>ISignalGroup</code> (<code>FibexElement</code>): Signal- und PDU-Definitionen für deterministische Buskommunikation.\n</li><li><code>SocketConnectionIpduIdentifierSet</code> (<code>FibexElement</code>): PDU-zu-Socket-Multiplexing über TCP/UDP.\n</li><li><code>EthIpProps</code>, <code>EthTcpIpProps</code>, <code>EthTcpIpIcmpProps</code> (<code>ARElement</code>): Parameter für IP/TCP/UDP/ICMP-Stacks (Subnetzmasken, MTU, Window Sizes).\n</li><li><code>NmConfig</code> (<code>FibexElement</code>): Network Management-Konfiguration (AUTOSAR NM / UDP NM).\n</li><li><code>GlobalTimeDomain</code> (<code>FibexElement</code>): Synchronisationsdomäne für gPTP / IEEE 802.1AS (ara::tsync).\n</li></ul>\n</li><li><strong>Security, Krypto &amp; Intrusion Detection (ara::crypto, IDS, Firewall):</strong>\n<ul class=\"fig-list\"><li><code>CryptoServicePrimitive</code>, <code>CryptoServiceKey</code>, <code>CryptoServiceCertificate</code> (<code>ARElement</code>): Spezifikation kryptografischer Primitive, Schlüssel und X.509-Zertifikate.\n</li><li><code>CryptoKeySlotUserDesign</code>, <code>CryptoKeySlotUserDesignMapping</code>, <code>CryptoKeySlotUsageDesignMapping</code>: Design-Elemente und Mappings zur Zuweisung und Nutzung von kryptografischen Key-Slots durch Applikationen und Plattformdienste.\n</li><li><code>SecureComProps</code>, <code>IPSecConfigProps</code> (<code>ARElement</code>): Parameter für gesicherte Kommunikationskanäle und IPsec.\n</li><li><code>MacSecParticipantSet</code>, <code>MacSecGlobalKeyProps</code> (<code>ARElement</code>): MACsec-Teilnehmer und globale Schlüssel auf Verbindungsschicht.\n</li><li><code>IdsDesign</code>, <code>IdsCommonElement</code> (<code>ARElement</code>), <code>SecurityEventReportToSecurityEventDefinitionMapping</code>: Intrusion Detection System (IDS) Architektur und Event-Mappings.\n</li><li><code>FirewallRule</code> (<code>ARElement</code>), <code>StateDependentFirewall</code>: Paketfilter und zustandsabhängige Firewall-Konfigurationen.\n</li></ul>\n</li><li><strong>Execution Management, State Management &amp; System-Topologie:</strong>\n<ul class=\"fig-list\"><li><code>Executable</code> (<code>AtpClassifier</code>): Definition ausführbarer Binärdateien im Software Package.\n</li><li><code>FunctionGroupSet</code> (<code>AtpClassifier</code>), <code>ModeDeclarationGroup</code> (<code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>): Funktionsgruppen und Modus-Deklarationen für State Management.\n</li><li><code>MachineDesign</code> (<code>AtpStructureElement</code>, <code>FibexElement</code>): Hardware- und Netzwerkarchitektur der Maschine.\n</li><li><code>System</code> (<code>ARElement</code>, <code>AtpStructureElement</code>): Systemweites Integrationsmodell.\n</li><li><code>Documentation</code> (<code>ARElement</code>): Dokumentations- und Spezifikationsmetadaten.\n</li></ul>\n</li><li><strong>Logging, Tracing &amp; End-to-End Protection:</strong>\n<ul class=\"fig-list\"><li><code>DltEcu</code>, <code>DltContext</code> (<code>ARElement</code>), <code>LogAndTraceMessageCollectionSet</code> (<code>ARElement</code>): Konfiguration für Diagnostic Log and Trace (ara::dlt).\n</li><li><code>E2EProfileConfigurationSet</code>, <code>E2EProfileCompatibilityProps</code> (<code>ARElement</code>): End-to-End-Absicherungsprofile und Kompatibilitätseigenschaften.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches AUTOSAR-Metamodell existiert kein direkter Call-Stack oder sequenzielles Laufzeitverhalten. Die dynamische Relevanz greift im <strong>UCM-Lifecycle</strong>:</p>\n<ol class=\"fig-list\"><li><strong>Paket-Ingestion:</strong> UCM (<code>ara::ucm</code>) empfängt ein Software Package (<code>SwPackage</code>), dessen Manifest auf <code>UploadablePackageElement</code> verweist.\n</li><li><strong>Metamodell-Auflösung:</strong> Der Manifest-Parser validiert die Subklassen von <code>UploadableDesignElement</code> gegen die Schemata der Plattform.\n</li><li><strong>Inkrementelle Rekonfiguration:</strong>\n<ul class=\"fig-list\"><li>Werden z. B. <code>FirewallRule</code> oder <code>StateDependentFirewall</code> aktualisiert, triggert der UCM-Aktivierungsschritt eine Neugenerierung bzw. Neuladung der OS-/Kernel-Netfilter-Tabellen.\n</li><li>Wird ein <code>ServiceInstanceToMachineMapping</code> aktualisiert, rekonfiguriert der ara::com Service-Discovery-Daemon (SOME/IP SD / DDS Discovery) die lokalen Endpunkte zur Laufzeit.\n</li><li>Änderungen an <code>ModeDeclarationGroup</code> oder <code>FunctionGroupSet</code> synchronisieren die Zustandsübergänge im Execution Management (<code>ara::exec</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>UCM-Granularität &amp; Entkopplung:</strong> Entwickler von Adaptive-Anwendungen müssen Design-Artefakte strikt modular modellieren. Da alle dargestellten Klassen eigenständige <code>UploadableDesignElement</code>-Objekte sind, können Netzwerkmatrizen (FIBEX/Signals), Diagnosekonfigurationen (DLT) und Sicherheitsrichtlinien getrennt von den eigentlichen Executables aktualisiert werden.\n</li><li><strong>Manifest-Generierung:</strong> Toolchains (Generatoren) kompilieren diese M2-Elemente in spezifische Manifeste:\n<ul class=\"fig-list\"><li><code>Executable</code>, <code>FunctionGroupSet</code> → <em>Execution Manifest</em> (<code>.arxml</code> / JSON / BSON).\n</li><li><code>ServiceInterfaceDeployment</code>, <code>ServiceInstanceToPortPrototypeMapping</code> → <em>Service Instance Manifest</em>.\n</li><li><code>MachineDesign</code>, <code>EthTcpIpProps</code>, <code>CryptoService*</code> → <em>Machine Manifest</em>.\n</li></ul>\n</li><li><strong>Variantenmanagement:</strong> Da <code>CommunicationCluster</code> das Stereotyp <code>«atpVariation»</code> trägt, müssen Post-Build- bzw. Pre-Compile-Variationspunkte aufgelöst sein, bevor UCM ein deploybares Artefakt bindet.\n</li><li><strong>Sicherheitsimplikation:</strong> Durch das Uploaden von <code>CryptoServiceKey</code>, <code>IPSecConfigProps</code> oder <code>FirewallRule</code> müssen strikte Signaturprüfungen und Zugriffsrechte (UCM-Authentifizierung) greifen, um unautorisierte Rekonfigurationen von IDS/Firewall-Subsystemen auf Machine-Ebene zu verhindern.\n</li></ul>"}], "trans": [{"from": "FIG-3badaa1e7ed83a48", "to": "FIG-129ae5813a2d9c71", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>AdaptivePlatformServiceInstance</code>: Als Subklasse von <code>UploadableDesignElement</code> explizit modelliert (korrigiert die zuvor leere Box unterhalb von <code>ServiceInstanceToMachineMapping</code>).\n</li><li><code>GenericTpConnection</code>: Neu als Subklasse von <code>UploadableDesignElement</code> hinzugefügt.\n</li><li><code>CryptoKeySlotUserDesign</code>: Neu als Subklasse von <code>UploadableDesignElement</code> hinzugefügt.\n</li><li><code>CryptoKeySlotUserDesignMapping</code>: Neu als Subklasse von <code>UploadableDesignElement</code> hinzugefügt.\n</li><li><code>CryptoKeySlotUsageDesignMapping</code>: Neu als Subklasse von <code>UploadableDesignElement</code> hinzugefügt.\n</li></ul>"}, {"from": "FIG-129ae5813a2d9c71", "to": "FIG-b319b061c3e65dce", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
